/**
 * generate-reference.js
 *
 * Generates NEW reference pages (from data/reference.json).
 * Does NOT touch existing /reference/ pages generated by earlier phases.
 *
 * reference/index.html           — hub (lists existing + new reference pages)
 * reference/<new-slug>.html      — individual pages from data/reference.json
 *
 * Idempotent — regenerates on every pipeline run.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const {
  fill, template, partial, SITE_HEADER, SITE_FOOTER, esc,
  buildBreadcrumb, buildRefContent, writeFile, ROOT, href, canonicalUrl, buildUrl,
  localizeRecord, chrome,
} = require('./template-utils');
const { htmlLangAttr } = require('../js/i18n/html-lang');
const { getLocalizedCanonical } = require('../js/i18n/locale-url');

const data = require(path.join(ROOT, 'data', 'reference.json'));
const REF_DIR = path.join(ROOT, 'reference');

// ── Discover existing reference pages ────────────────────────────────────────

function existingRefPages() {
  if (!fs.existsSync(REF_DIR)) return [];
  return fs.readdirSync(REF_DIR)
    .filter(f => f.endsWith('.html') && f !== 'index.html')
    .map(f => {
      const slug = path.parse(f).name;
      const title = slug.replace(/-/g, ' ')
        .replace(/\b[a-z]/g, c => c.toUpperCase());
      return { href: href(`/reference/${slug}`), label: title };
    });
}

// ── Hub page ──────────────────────────────────────────────────────────────────

function generateHub() {
  const existing = existingRefPages();
  const newPages = data.pages || [];
  const allPages = [
    ...existing,
    ...newPages.map(p => ({ href: href(p.slug), label: p.title })),
  ];

  const refCards = allPages.length > 0
    ? allPages.map(p =>
        `      <a href="${p.href}" class="knowledge-card">
        <div class="knowledge-card-title">${esc(p.label)}</div>
      </a>`).join('\n')
    : `      <div class="knowledge-callout">
        <span class="knowledge-callout-icon">&#128197;</span>
        <div><strong>Reference pages are coming.</strong> Use the <a href="${href('/reference/pool-chemistry-reference')}">Pool Chemistry Reference</a> to get started.</div>
      </div>`;

  const bc = buildBreadcrumb('reference', 'Reference');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <link rel="canonical" href="${canonicalUrl('/reference')}">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Pool Chemistry Reference | WaterBalanceTools</title>
  <meta name="description" content="Reference tables, target ranges, and chemical data for pool and hot tub water chemistry. Ideal ranges for chlorine, pH, alkalinity, hardness, and CYA.">
  <link rel="stylesheet" href="/style.css">
  <link rel="stylesheet" href="/knowledge.css">
  <script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-3974004697476579" crossorigin="anonymous"></script>
  ${bc.schema}
</head>
<body class="knowledge-page reference-hub">
${SITE_HEADER}
${bc.nav}
  <main class="container">
    <section class="knowledge-hub-hero">
      <span class="knowledge-badge knowledge-badge--reference">Reference</span>
      <h1>Pool Chemistry Reference</h1>
      <p>Quick-access reference tables, target ranges, and dosing data for pool and hot tub water chemistry.</p>
    </section>
    <section>
      <h2>All Reference Pages</h2>
      <div class="knowledge-grid knowledge-grid--2col">
${refCards}
      </div>
    </section>
    <section class="link-matrix">
      <h3>Related</h3>
      <ul>
        <li><a href="${href('/academy')}">Chemistry Academy</a></li>
        <li><a href="${href('/formulas')}">Formula Library</a></li>
        <li><a href="${href('/glossary')}">Glossary</a></li>
        <li><a href="${href('/calculators/chemical-calculator')}">Pool Chemical Calculator</a></li>
      </ul>
    </section>
  </main>
${SITE_FOOTER}
  <script src="/js/nav.js" defer></script>
</body>
</html>`;
}

// ── Individual reference page ─────────────────────────────────────────────────

function generateRefPage(page, locale) {
  const effectiveLocale = locale || 'en';
  const tpl = template('reference-template.html');
  // Phase 8N: localizeRecord() overlays page.es (title/description/
  // summary/overview/notes/checklists, and per-table titles only --
  // headers/rows stay English, a documented scope limitation) for
  // locale 'es'.
  const p = localizeRecord(page, effectiveLocale);
  const bc = buildBreadcrumb(buildUrl(page.slug), p.title, effectiveLocale);

  // Drop the "| Reference" segment only when the full title would exceed
  // the 65-char SEO threshold -- keeps the category marker on every page
  // where it fits, per Phase 7I (7 of ~70 reference titles needed this).
  const categoryLabel = effectiveLocale === 'es' ? 'Referencia' : 'Reference';
  const titleWithCategory = `${p.title} | ${categoryLabel} | WaterBalanceTools`;
  const pageTitle = titleWithCategory.length <= 65 ? titleWithCategory : `${p.title} | WaterBalanceTools`;

  return fill(tpl, {
    SLUG:              page.slug,
    HTML_LANG_ATTR:    htmlLangAttr(effectiveLocale),
    CANONICAL_URL:     getLocalizedCanonical('/' + page.slug, effectiveLocale),
    PAGE_TITLE:        pageTitle,
    H1_TITLE:          p.title,
    META_DESCRIPTION:  p.description,
    LAST_REVIEWED:     page.lastReviewed || '2026-06-01',
    BREADCRUMB:        bc.nav,
    BREADCRUMB_SCHEMA: bc.schema,
    ARIA_PRIMARY_NAV:    chrome('ariaPrimaryNav', effectiveLocale),
    NAV_CALCULATOR_HREF: chrome('navCalculatorHref', effectiveLocale),
    NAV_CALCULATOR_LABEL: chrome('navCalculatorLabel', effectiveLocale),
    NAV_RESOURCES:       chrome('navResources', effectiveLocale),
    NAV_CHARTS:          chrome('navCharts', effectiveLocale),
    NAV_ACADEMY:         chrome('navAcademy', effectiveLocale),
    NAV_GUIDES:          chrome('navGuides', effectiveLocale),
    NAV_ABOUT:           chrome('navAbout', effectiveLocale),
    ARIA_SEARCH:         chrome('ariaSearch', effectiveLocale),
    ARIA_OPEN_MENU:      chrome('ariaOpenMenu', effectiveLocale),
    LAST_REVIEWED_LABEL: chrome('lastReviewedLabel', effectiveLocale),
    HERO: fill(partial('knowledge-hero.html'), {
      BADGE:         categoryLabel,
      BADGE_CLASS:   'knowledge-badge--reference',
      READING_TIME:  page.readingTime || (effectiveLocale === 'es' ? '2 min de lectura' : '2 min read'),
      LAST_REVIEWED: page.lastReviewed || '2026-06-01',
      TITLE:         esc(p.title),
      SUMMARY:       esc(p.summary || ''),
      CHIPS:         effectiveLocale === 'es'
        ? '<a href="#overview" class="knowledge-chip">Resumen</a>'
        : '<a href="#overview" class="knowledge-chip">Overview</a>',
    }),
    CONTENT:           buildRefContent(p, effectiveLocale),
    SIDEBAR:           '',
    RELATED_TOOLS:     '',
    RELATED_TOPICS:    '',
    KNOWLEDGE_FOOTER:  '',
    SITE_FOOTER:       SITE_FOOTER,
  });
}

// ── Run ───────────────────────────────────────────────────────────────────────

let written = 0;

writeFile(path.join(REF_DIR, 'index.html'), generateHub());
written++;
console.log('  → reference/index.html');

for (const page of (data.pages || [])) {
  const outPath = path.join(ROOT, `${page.slug}.html`);
  writeFile(outPath, generateRefPage(page));
  written++;
  console.log(`  → ${page.slug}.html`);
}

console.log(`generate-reference: wrote ${written} files (${(data.pages || []).length} new reference pages)`);

// Phase 8N: exported so scripts/generate-spanish-knowledge-cluster.js can
// call generateRefPage(page, 'es') without a second implementation.
module.exports = { generateRefPage, data };
